    const CONCURRENCY = 4;
    const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
    let index = 0, active = 0, closed = false;
    const pending = new Set<Promise<void>>();
    await new Promise<void>(resolve => {
      const maybeDone = () => { if (closed && active === 0) resolve(); };
      rl.on('line', line => {
        if (!line.trim()) return;
        const current = index++;
        let record: LogInput;
        try { record = parseRecord(line, current); } catch (error) { console.error(`jevlogs: skipped line ${current + 1}: ${error instanceof Error ? error.message : 'invalid record'}`); return; }
        active++;
        if (active >= CONCURRENCY) rl.pause();
        const task = jev.triage(record).then(decision => printDecision(current, mode, record, decision, json)).finally(() => { active--; pending.delete(task); if (active < CONCURRENCY) rl.resume(); maybeDone(); });
        pending.add(task);
      });
      rl.once('close', () => { closed = true; maybeDone(); });
    });
    finish();
    return;
  }
  let records = samples;
  if (file || stdin) {
    if (file && (await stat(file)).size > MAX_BYTES) throw new Error('Input exceeds 1 MiB. Pass a smaller file.');
    const text = file ? await readFile(file, 'utf8') : await stdinText();
    if (Buffer.byteLength(text) > MAX_BYTES) throw new Error('Input exceeds 1 MiB.');
    const lines = text.split(/\r?\n/).filter(line => line.trim());
    if (!lines.length) throw new Error('No log records found.');
    if (lines.length > limit) console.error(`Processing the first ${limit} of ${lines.length} records; raise --limit up to 100 to include more.`);
    records = lines.slice(0, limit).map(parseRecord);
  } else records = samples.slice(0, limit);
  for (let i = 0; i < records.length; i++) {
    const record = records[i]!;
    demoIndex = i;
    printDecision(i, mode, record, await jev.triage(record), json);
  }
  finish();
}

export async function loadJevConfig(path?: string): Promise<JevConfig> {
  const filename = resolve(path ?? 'jevlogs.config.json');
  let text: string;
  try { text = await readFile(filename, 'utf8'); }
  catch (error) { if (!path && (error as NodeJS.ErrnoException).code === 'ENOENT') return {}; throw new Error(`Cannot read config: ${filename}`); }
  let value: unknown;
  try { value = JSON.parse(text); } catch { throw new Error('jevlogs config must be valid JSON'); }
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('jevlogs config must be an object');
  const config = value as Record<string, unknown>;
  for (const key of Object.keys(config)) if (!KEYS.includes(key)) throw new Error(`Unknown config option: ${key}`);
  for (const key of ['port', 'retainBelow', 'timeoutMs', 'maxInputChars', 'cacheSize', 'cacheTtlMs']) if (config[key] !== undefined && (typeof config[key] !== 'number' || !Number.isFinite(config[key]))) throw new Error(`Config ${key} must be a finite number`);
  if (config.envFile !== undefined) {
    if (typeof config.envFile !== 'string' || !config.envFile.trim()) throw new Error('Config envFile must be a path');
    try { loadEnvFile(resolve(dirname(filename), config.envFile)); } catch { throw new Error('Cannot load configured envFile'); }
  }
  if (config.forwardUrl !== undefined) {
    let url: URL;
    try { url = new URL(String(config.forwardUrl)); } catch { throw new Error('Config forwardUrl must be an absolute http(s) URL'); }
    if (typeof config.forwardUrl !== 'string' || !['http:', 'https:'].includes(url.protocol)) throw new Error('Config forwardUrl must be an absolute http(s) URL');
  }
  if (config.forwardMode !== undefined && config.forwardMode !== 'annotate' && config.forwardMode !== 'analysis-only') throw new Error('Config forwardMode must be "annotate" or "analysis-only"');
  if (config.forwardMode !== undefined && config.forwardUrl === undefined) throw new Error('Config forwardMode requires forwardUrl');
  if (config.rules !== undefined) {
    try { compileRules(config.rules as Rule[]); } catch (error) { throw new Error(`Config ${error instanceof Error ? error.message : 'rules are invalid'}`); }
  }
  const { cacheSize, cacheTtlMs, ...rest } = config;
  const result: JevConfig = rest as JevConfig;
  if (cacheSize === 0) result.cache = false;
  else if (cacheSize !== undefined || cacheTtlMs !== undefined) result.cache = { ...(cacheSize === undefined ? {} : { maxEntries: cacheSize as number }), ...(cacheTtlMs === undefined ? {} : { ttlMs: cacheTtlMs as number }) };
  return result;
}

export function compileRules(rules: Rule[] | undefined): CompiledRule[] {
  if (rules === undefined) return [];
  if (!Array.isArray(rules) || rules.length > 200) throw new RangeError('rules must be an array of at most 200 rules');
  return rules.map((rule, index) => {
    const label = `rules[${index}]`;
    if (!rule || typeof rule !== 'object') throw new RangeError(`${label} must be an object`);
    if (rule.route !== 'retain' && rule.route !== 'analyze') throw new RangeError(`${label}.route must be "retain" or "analyze"`);
    if (rule.name !== undefined && (typeof rule.name !== 'string' || !rule.name.trim() || rule.name.length > 64)) throw new RangeError(`${label}.name must be a short string`);
    const name = rule.name ?? `rule-${index + 1}`;
    if (rule.match instanceof RegExp) return { name, regex: new RegExp(rule.match.source, rule.match.flags.replace(/[gy]/g, '')), route: rule.route };
    if (typeof rule.match !== 'string' || !rule.match || rule.match.length > 512) throw new RangeError(`${label}.match must be a regular expression string of at most 512 characters`);
    const flags = rule.flags ?? '';
    if (typeof flags !== 'string' || !/^[imsu]*$/.test(flags)) throw new RangeError(`${label}.flags may only contain i, m, s or u`);
    try { return { name, regex: new RegExp(rule.match, flags), route: rule.route }; }
    catch (error) { throw new RangeError(`${label}.match is not a valid regular expression: ${error instanceof Error ? error.message : 'syntax error'}`); }
  });
}

