async triage(log: LogInput): Promise<Decision> {
      if (log.protected || (log.severityNumber ?? 0) >= 17 || /^(ERROR|FATAL|CRITICAL)$/i.test(log.severityText ?? '')) return record({ ...fallback('protected'), priority: 'critical' });
